9		"strconv"
10		"strings"
11		"testing"
12	)
13	
14	// The trace sends its probes itself, over ICMP and UDP sockets. It must never
15	// start a child process (traceroute, ping) nor replace the process image, on
16	// any platform. The guard reads every .go file of the package whatever its
17	// build constraints (go/parser does not evaluate them), so a file that only
18	// builds on another OS is covered too.
19	
20	// bannedImports are packages that must not be imported at all.
21	var bannedImports = map[string]bool{
22		"os/exec":                  true,
23		"golang.org/x/sys/execabs": true,
24	}
25	
26	// dotWatched are packages that must not be dot-imported: a dot-import hides
27	// the package name the selector check relies on.
28	var dotWatched = map[string]bool{
29		"os":                    true,
30		"syscall":               true,
31		"os/exec":               true,
32		"golang.org/x/sys/unix": true,
33	}
34	
35	// bannedSymbols maps an import path to the process-launching symbols it must
36	// not expose here, called or not (`f := os.StartProcess` is caught too). The
37	// socket symbols the engine needs (Recvmsg, Setsockopt...) stay allowed.
38	var bannedSymbols = map[string]map[string]bool{
39		"os": {"StartProcess": true},
40		"syscall": {
41			"StartProcess": true, "ForkExec": true, "Exec": true,
42			"Syscall": true, "Syscall6": true, "RawSyscall": true, "RawSyscall6": true,
43		},
44		"golang.org/x/sys/unix": {
45			"Exec":    true,
46			"Syscall": true, "Syscall6": true, "RawSyscall": true, "RawSyscall6": true,
47		},
48	}
49	
50	// guardSource returns one message per offence in src ("name:line: ...").
51	func guardSource(fset *token.FileSet, name string, src any) ([]string, error) {
52		file, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
53		if err != nil {
54			return nil, err
55		}
56		var out []string
57		local := map[string]string{} // local package name -> import path
58		for _, imp := range file.Imports {
59			path, _ := strconv.Unquote(imp.Path.Value)
60			if bannedImports[path] {
61				out = append(out, fmt.Sprintf("%s: import of %s", fset.Position(imp.Pos()), path))
62			}
63			if imp.Name != nil && imp.Name.Name == "." && dotWatched[path] {
64				out = append(out, fmt.Sprintf("%s: dot-import of %s", fset.Position(imp.Pos()), path))
65			}
66			if _, watched := bannedSymbols[path]; !watched {
67				continue
68			}
69			n := path[strings.LastIndex(path, "/")+1:]
70			if imp.Name != nil {
71				n = imp.Name.Name
72			}
73			local[n] = path
74		}
75		ast.Inspect(file, func(n ast.Node) bool {
76			sel, ok := n.(*ast.SelectorExpr)
77			if !ok {
78				return true
79			}
80			id, ok := sel.X.(*ast.Ident)
81			if !ok {
82				return true
83			}
84			if path, ok := local[id.Name]; ok && bannedSymbols[path][sel.Sel.Name] {
85				out = append(out, fmt.Sprintf("%s: use of %s.%s", fset.Position(sel.Pos()), id.Name, sel.Sel.Name))
86			}
87			return true
88		})
89		return out, nil
90	}
91	
92	func TestGuardSourceFlagsOffences(t *testing.T) {
93		for _, c := range []struct {
94			name, src string
95			want      int
96		}{
97			{"exec.go", "package x\nimport \"os/exec\"\nfunc f() { _ = exec.Command(\"traceroute\") }\n", 1},
98			{"aliased_exec.go", "package x\nimport e \"os/exec\"\nvar _ = e.Command\n", 1},
99			{"startprocess.go", "package x\nimport \"os\"\nfunc f() { _, _ = os.StartProcess(\"a\", nil, nil) }\n", 1},
100			{"forkexec.go", "package x\nimport \"syscall\"\nfunc f() { _, _ = syscall.ForkExec(\"a\", nil, nil); _ = syscall.Exec(\"a\", nil, nil) }\n", 2},
101			{"unix.go", "package x\nimport \"golang.org/x/sys/unix\"\nfunc f() { _ = unix.Exec(\"a\", nil, nil) }\n", 1},
102			{"aliased_unix.go", "package x\nimport u \"golang.org/x/sys/unix\"\nfunc f() { _ = u.Exec(\"a\", nil, nil) }\n", 1},
103			{"tagged.go", "//go:build windows\n\npackage x\nimport \"os/exec\"\nvar _ = exec.Command\n", 1},
104			{"execabs.go", "package x\nimport \"golang.org/x/sys/execabs\"\nvar _ = execabs.Command\n", 1},
105			{"syscall_startprocess.go", "package x\nimport \"syscall\"\nfunc f() { _, _ = syscall.StartProcess(\"a\", nil, nil) }\n", 1},
106			{"raw_syscall.go", "package x\nimport \"syscall\"\nfunc f() { syscall.RawSyscall(59, 0, 0); syscall.Syscall(59, 0, 0, 0); syscall.Syscall6(59, 0, 0, 0, 0, 0, 0); syscall.RawSyscall6(59, 0, 0, 0, 0, 0, 0) }\n", 4},
107			{"unix_syscall.go", "package x\nimport \"golang.org/x/sys/unix\"\nfunc f() { unix.Syscall(59, 0, 0, 0); unix.RawSyscall6(59, 0, 0, 0, 0, 0, 0) }\n", 2},
108			{"func_value.go", "package x\nimport \"os\"\nvar f = os.StartProcess\n", 1},
109			{"dot_os.go", "package x\nimport . \"os\"\nvar _ = Getpid\n", 1},
110			{"dot_syscall.go", "package x\nimport . \"syscall\"\nvar _ = Getpid\n", 1},
111			{"dot_exec.go", "package x\nimport . \"os/exec\"\nvar _ = Command\n", 2},
112			{"dot_unix.go", "package x\nimport . \"golang.org/x/sys/unix\"\nvar _ = Getpid\n", 1},
113			{"allowed_unix.go", "package x\nimport \"golang.org/x/sys/unix\"\nfunc f() { _ = unix.Setsockopt; _ = unix.Recvmsg }\n", 0},
114			{"clean.go", "package x\nimport (\"os\"; \"syscall\")\n// os.StartProcess in a comment is not a call\nfunc f() { _ = os.Getpid(); _ = syscall.Getpid(); var s struct{ Exec func() }; s.Exec() }\n", 0},
115		} {
116			got, err := guardSource(token.NewFileSet(), c.name, c.src)
117			if err != nil {
118				t.Fatalf("%s: %v", c.name, err)
119			}
120			if len(got) != c.want {
121				t.Errorf("%s: got %d offences %v, want %d", c.name, len(got), got, c.want)
122			}
123		}
124	}
125	
126	func TestPackageNeverStartsAProcess(t *testing.T) {
127		entries, err := os.ReadDir(".")
128		if err != nil {
129			t.Fatal(err)
130		}
131		fset := token.NewFileSet()
132		files := 0
133		for _, e := range entries {
134			if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
135				continue
136			}
137			src, err := os.ReadFile(e.Name())
138			if err != nil {
139				t.Fatal(err)
140			}
141			files++
142			offences, err := guardSource(fset, e.Name(), src)
143			if err != nil {
144				t.Errorf("%s: %v", e.Name(), err)
145				continue
146			}
147			for _, o := range offences {
148				t.Error(o + ": the trace must not start or exec a process")
149			}
150		}
151		if files == 0 {
152			t.Error("the scan saw no Go file: the guard would pass vacuously")
153		}
154	}
